 * Creates a project once''','''/** Roles and staff flag that see every private project in their org. */
function seesAllProjects(actor: Actor): boolean {
  return (
    actor.isPlatformStaff === true ||
    actor.role === "admin" ||
    actor.role === "owner"
  );
}

/**
 * Whether `actor` may see `project` and everything in it. Only `private`
 * projects are restricted: admins, owners, platform staff, the lead and
 * explicit project members get through. Membership is read on every call, so
 * changes apply immediately.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (project.visibility !== "private") return true;
  if (actor.orgId !== project.orgId) return false;
  if (seesAllProjects(actor)) return true;
  if (project.leadId !== null && project.leadId === actor.userId) return true;
  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/** Makes a project the actor cannot see indistinguishable from a missing one. */
export async function assertProjectVisible(
  actor: Actor,
  project: Project,
  entity = "Project",
  id: string = project.id,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError(entity, id);
  }
}

/** Same, for an issue: visibility is inherited from its project. */
export async function assertIssueVisible(
  actor: Actor,
  issue: Issue,
): Promise<void> {
  const project = await projectRepo.findProjectById(
    issue.orgId,
    issue.projectId,
  );
  if (project === null) return;
  await assertProjectVisible(actor, project, "Issue", issue.id);
}

/**
 * Repository viewer restriction for listings: `undefined` when the actor sees
 * every project, otherwise the user the listing must be narrowed to.
 */
export function listingViewer(
  actor: Actor,
): { readonly userId: Actor["userId"] } | undefined {
  return seesAllProjects(actor) ? undefined : { userId: actor.userId };
}

